H.background();
const C = Math.max(P.C, 0.001);
const pKa = Math.max(P.pKa, 0);
const Ka = Math.pow(10, -pKa);
const pCl = -Math.log10(C);
const hWeak = (-Ka + Math.sqrt(Ka * Ka + 4 * Ka * C)) / 2;
const pWeak = -Math.log10(Math.max(hWeak, 1e-14));
const sweep = 0.5 + 0.5 * Math.sin(t * 0.8);
H.text("Strong vs weak acid at the same concentration", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Strong fully ionizes (pH=-log C); weak only partly, so higher pH.", 24, 52, { color: H.colors.sub, size: 13 });
function bar(x, label, pH, col) {
  const bx = x, by = H.H - 90, bw = 110, maxH = H.H - 220;
  const h = Math.max(4, (pH / 14) * maxH);
  H.rect(bx, by - h, bw, h, { fill: col });
  H.text(label, bx + bw / 2, by + 20, { color: H.colors.sub, size: 13, align: "center" });
  H.text("pH " + pH.toFixed(2), bx + bw / 2, by - h - 12, { color: col, size: 14, align: "center", weight: 700 });
}
bar(H.W * 0.28 - 55, "strong (HCl)", pCl, H.colors.warn);
bar(H.W * 0.62 - 55, "weak (Ka)", pWeak, H.colors.accent);
H.line(H.W - 60, 90, H.W - 60, H.H - 90, { color: H.colors.grid, width: 2 });
for (let i = 0; i <= 14; i += 2) {
  const yy = (H.H - 90) - (i / 14) * (H.H - 220);
  H.text(String(i), H.W - 40, yy, { color: H.colors.sub, size: 11, baseline: "middle" });
}
const ny = (H.H - 90) - (7 / 14) * (H.H - 220);
H.line(H.W * 0.18, ny, H.W - 60, ny, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.text("neutral pH 7", H.W * 0.18, ny - 8, { color: H.colors.sub, size: 11 });
H.circle(H.W * 0.28, (H.H - 90) - (pCl / 14) * (H.H - 220) * sweep, 5, { fill: H.colors.warn });
H.text("C = " + C.toFixed(3) + " M,  pKa = " + pKa.toFixed(1), 24, H.H - 50, { color: H.colors.violet, size: 13 });
H.text("dpH (weak - strong) = +" + (pWeak - pCl).toFixed(2), 24, H.H - 28, { color: H.colors.good, size: 14 });
